/// Input data for llama_encode/llama_decode A llama_batch object can contain
/// input about one or many sequences The provided arrays (i.e. token, embd,
/// pos, etc.) must have size of n_tokens
final class llama_batch extends ffi.Struct {
  @ffi.Int32()
  external int n_tokens;

  external ffi.Pointer<ffi.Int32> token;

  external ffi.Pointer<ffi.Float> embd;

  external ffi.Pointer<ffi.Int32> pos;

  external ffi.Pointer<ffi.Int32> n_seq_id;

  external ffi.Pointer<ffi.Pointer<ffi.Int32>> seq_id;

  /// TODO: rename this to "output"
  external ffi.Pointer<ffi.Int8> logits;

  static ffi.Pointer<llama_batch> $allocate(
    ffi.Allocator $allocator, {
    required int n_tokens,
    required ffi.Pointer<ffi.Int32> token,
    required ffi.Pointer<ffi.Float> embd,
    required ffi.Pointer<ffi.Int32> pos,
    required ffi.Pointer<ffi.Int32> n_seq_id,
    required ffi.Pointer<ffi.Pointer<ffi.Int32>> seq_id,
    required ffi.Pointer<ffi.Int8> logits,
  }) => $allocator<llama_batch>()
    ..ref.n_tokens = n_tokens
    ..ref.token = token
    ..ref.embd = embd
    ..ref.pos = pos
    ..ref.n_seq_id = n_seq_id
    ..ref.seq_id = seq_id
    ..ref.logits = logits;
}

/// used in chat template
final class llama_chat_message extends ffi.Struct {
  external ffi.Pointer<ffi.Char> role;

  external ffi.Pointer<ffi.Char> content;

  static ffi.Pointer<llama_chat_message> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Char> role,
    required ffi.Pointer<ffi.Char> content,
  }) => $allocator<llama_chat_message>()
    ..ref.role = role
    ..ref.content = content;
}

final class llama_context extends ffi.Opaque {}

/// NOTE: changing the default values of parameters marked as [EXPERIMENTAL] may
/// cause crashes or incorrect results in certain configurations
/// https://github.com/ggml-org/llama.cpp/pull/7544
final class llama_context_params extends ffi.Struct {
  /// text context, 0 = from model
  @ffi.Uint32()
  external int n_ctx;

  /// logical maximum batch size that can be submitted to llama_decode
  @ffi.Uint32()
  external int n_batch;

  /// physical maximum batch size
  @ffi.Uint32()
  external int n_ubatch;

  /// max number of sequences (i.e. distinct states for recurrent models)
  @ffi.Uint32()
  external int n_seq_max;

  /// number of recurrent-state snapshots per seq for rollback (0 = no rollback)
  /// [EXPERIMENTAL]
  @ffi.Uint32()
  external int n_rs_seq;

  /// max outputs in a ubatch (0 = n_batch)
  @ffi.Uint32()
  external int n_outputs_max;

  /// max outputs per sequence (0 = n_outputs_max)
  @ffi.Uint32()
  external int n_outputs_max_per_seq;

  /// number of threads to use for generation
  @ffi.Int32()
  external int n_threads;

  /// number of threads to use for batch processing
  @ffi.Int32()
  external int n_threads_batch;

  /// set the context type (e.g. MTP)
  @ffi.UnsignedInt()
  external int ctx_typeAsInt;

  llama_context_type get ctx_type =>
      llama_context_type.fromValue(ctx_typeAsInt);
  set ctx_type(llama_context_type value) => ctx_typeAsInt = value.value;

  /// RoPE scaling type, from `enum llama_rope_scaling_type`
  @ffi.Int()
  external int rope_scaling_typeAsInt;

  llama_rope_scaling_type get rope_scaling_type =>
      llama_rope_scaling_type.fromValue(rope_scaling_typeAsInt);
  set rope_scaling_type(llama_rope_scaling_type value) =>
      rope_scaling_typeAsInt = value.value;

  /// whether to pool (sum) embedding results by sequence id
  @ffi.Int()
  external int pooling_typeAsInt;

  llama_pooling_type get pooling_type =>
      llama_pooling_type.fromValue(pooling_typeAsInt);
  set pooling_type(llama_pooling_type value) => pooling_typeAsInt = value.value;

  /// attention type to use for embeddings
  @ffi.Int()
  external int attention_typeAsInt;

  llama_attention_type get attention_type =>
      llama_attention_type.fromValue(attention_typeAsInt);
  set attention_type(llama_attention_type value) =>
      attention_typeAsInt = value.value;

  /// when to enable Flash Attention
  @ffi.Int()
  external int flash_attn_typeAsInt;

  llama_flash_attn_type get flash_attn_type =>
      llama_flash_attn_type.fromValue(flash_attn_typeAsInt);
  set flash_attn_type(llama_flash_attn_type value) =>
      flash_attn_typeAsInt = value.value;

  /// RoPE base frequency, 0 = from model
  @ffi.Float()
  external double rope_freq_base;

  /// RoPE frequency scaling factor, 0 = from model
  @ffi.Float()
  external double rope_freq_scale;

  /// YaRN extrapolation mix factor, negative = from model
  @ffi.Float()
  external double yarn_ext_factor;

  /// YaRN magnitude scaling factor
  @ffi.Float()
  external double yarn_attn_factor;

  /// YaRN low correction dim
  @ffi.Float()
  external double yarn_beta_fast;

  /// YaRN high correction dim
  @ffi.Float()
  external double yarn_beta_slow;

  /// YaRN original context size
  @ffi.Uint32()
  external int yarn_orig_ctx;

  /// [DEPRECATED] defragment the KV cache if holes/size > thold, <= 0 disabled
  /// (default)
  @ffi.Float()
  external double defrag_thold;

  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.Bool Function(
        ffi.Pointer<ggml_tensor> t,
        ffi.Bool ask,
        ffi.Pointer<ffi.Void> user_data,
      )
    >
  >
  cb_eval;

  external ffi.Pointer<ffi.Void> cb_eval_user_data;

  /// data type for K cache [EXPERIMENTAL]
  @ffi.UnsignedInt()
  external int type_kAsInt;

  ggml_type get type_k => ggml_type.fromValue(type_kAsInt);
  set type_k(ggml_type value) => type_kAsInt = value.value;

  /// data type for V cache [EXPERIMENTAL]
  @ffi.UnsignedInt()
  external int type_vAsInt;

  ggml_type get type_v => ggml_type.fromValue(type_vAsInt);
  set type_v(ggml_type value) => type_vAsInt = value.value;

  /// Abort callback if it returns true, execution of llama_decode() will be
  /// aborted currently works only with CPU execution
  external ffi.Pointer<
    ffi.NativeFunction<ffi.Bool Function(ffi.Pointer<ffi.Void> data)>
  >
  abort_callback;

  external ffi.Pointer<ffi.Void> abort_callback_data;

  /// if true, extract embeddings (together with logits)
  @ffi.Bool()
  external bool embeddings;

  /// offload the KQV ops (including the KV cache) to GPU
  @ffi.Bool()
  external bool offload_kqv;

  /// measure performance timings
  @ffi.Bool()
  external bool no_perf;

  /// offload host tensor operations to device
  @ffi.Bool()
  external bool op_offload;

  /// use full-size SWA cache
  /// (https://github.com/ggml-org/llama.cpp/pull/13194#issuecomment-2868343055)
  /// NOTE: setting to false when n_seq_max > 1 can cause bad performance in
  /// some cases ref:
  /// https://github.com/ggml-org/llama.cpp/pull/13845#issuecomment-2924800573
  @ffi.Bool()
  external bool swa_full;

  /// use a unified buffer across the input sequences when computing the
  /// attention try to disable when n_seq_max > 1 for improved performance when
  /// the sequences do not share a large prefix ref:
  /// https://github.com/ggml-org/llama.cpp/pull/14363
  @ffi.Bool()
  external bool kv_unified;

  /// [EXPERIMENTAL] backend sampler chain configuration (make sure the caller
  /// keeps the sampler chains alive) note: the samplers must be sampler chains
  /// (i.e. use llama_sampler_chain_init)
  external ffi.Pointer<llama_sampler_seq_config> samplers;

  @ffi.Size()
  external int n_samplers;

  /// a source/target/parent context can be utilized in various ways, for
  /// example by sharing results or llama_memory between 2 contexts
  external ffi.Pointer<llama_context> ctx_other;

  static ffi.Pointer<llama_context_params> $allocate(
    ffi.Allocator $allocator, {
    required int n_ctx,
    required int n_batch,
    required int n_ubatch,
    required int n_seq_max,
    required int n_rs_seq,
    required int n_outputs_max,
