enum llama_context_type {
  LLAMA_CONTEXT_TYPE_DEFAULT(0),
  LLAMA_CONTEXT_TYPE_MTP(1);

  final int value;
  const llama_context_type(this.value);

  static llama_context_type fromValue(int value) => switch (value) {
    0 => LLAMA_CONTEXT_TYPE_DEFAULT,
    1 => LLAMA_CONTEXT_TYPE_MTP,
    _ => throw ArgumentError('Unknown value for llama_context_type: $value'),
  };
}

enum llama_flash_attn_type {
  LLAMA_FLASH_ATTN_TYPE_AUTO(-1),
  LLAMA_FLASH_ATTN_TYPE_DISABLED(0),
  LLAMA_FLASH_ATTN_TYPE_ENABLED(1);

  final int value;
  const llama_flash_attn_type(this.value);

  static llama_flash_attn_type fromValue(int value) => switch (value) {
    -1 => LLAMA_FLASH_ATTN_TYPE_AUTO,
    0 => LLAMA_FLASH_ATTN_TYPE_DISABLED,
    1 => LLAMA_FLASH_ATTN_TYPE_ENABLED,
    _ => throw ArgumentError('Unknown value for llama_flash_attn_type: $value'),
  };
}

enum llama_lazy_mode {
  /// always read the whole tensor up front
  LLAMA_LAZY_MODE_OFF(0),

  /// lazy only for marked tensors larger than 4 GiB (requires mmap)
  LLAMA_LAZY_MODE_AUTO(1),

  /// read the rows of tensors marked by the arch on demand (requires mmap)
  LLAMA_LAZY_MODE_ON(2);

  final int value;
  const llama_lazy_mode(this.value);

  static llama_lazy_mode fromValue(int value) => switch (value) {
    0 => LLAMA_LAZY_MODE_OFF,
    1 => LLAMA_LAZY_MODE_AUTO,
    2 => LLAMA_LAZY_MODE_ON,
    _ => throw ArgumentError('Unknown value for llama_lazy_mode: $value'),
  };
}

enum llama_load_mode {
  /// auto-detect based on device capabilities
  LLAMA_LOAD_MODE_AUTO(-1),

  /// no special loading mode
  LLAMA_LOAD_MODE_NONE(0),

  /// memory map the model
  LLAMA_LOAD_MODE_MMAP(1),

  /// force system to keep model in RAM rather than swapping or compressing
  LLAMA_LOAD_MODE_MLOCK(2),

  /// mmap + force system to keep model in RAM rather than swapping or
  /// compressing
  LLAMA_LOAD_MODE_MMAP_MLOCK(3),

  /// use direct I/O if available
  LLAMA_LOAD_MODE_DIRECT_IO(4);

  final int value;
  const llama_load_mode(this.value);

  static llama_load_mode fromValue(int value) => switch (value) {
    -1 => LLAMA_LOAD_MODE_AUTO,
    0 => LLAMA_LOAD_MODE_NONE,
    1 => LLAMA_LOAD_MODE_MMAP,
    2 => LLAMA_LOAD_MODE_MLOCK,
    3 => LLAMA_LOAD_MODE_MMAP_MLOCK,
    4 => LLAMA_LOAD_MODE_DIRECT_IO,
    _ => throw ArgumentError('Unknown value for llama_load_mode: $value'),
  };
}

