final class llama_model_kv_override extends ffi.Opaque {}

final class llama_model_params extends ffi.Struct {
  /// NULL-terminated list of devices to use for offloading (if NULL, all
  /// available devices are used)
  external ffi.Pointer<ffi.Pointer<ggml_backend_device>> devices;

  /// NULL-terminated list of buffer types to use for tensors that match a
  /// pattern
  external ffi.Pointer<llama_model_tensor_buft_override> tensor_buft_overrides;

  /// number of layers to store in VRAM, a negative value means all layers
  @ffi.Int32()
  external int n_gpu_layers;

  /// how to split the model across multiple GPUs
  @ffi.UnsignedInt()
  external int split_modeAsInt;

  llama_split_mode get split_mode =>
      llama_split_mode.fromValue(split_modeAsInt);
  set split_mode(llama_split_mode value) => split_modeAsInt = value.value;

  /// how to load the model
  @ffi.Int()
  external int load_modeAsInt;

  llama_load_mode get load_mode => llama_load_mode.fromValue(load_modeAsInt);
  set load_mode(llama_load_mode value) => load_modeAsInt = value.value;

  /// on-demand reading of tensors marked by the arch
  @ffi.UnsignedInt()
  external int lazy_modeAsInt;

  llama_lazy_mode get lazy_mode => llama_lazy_mode.fromValue(lazy_modeAsInt);
  set lazy_mode(llama_lazy_mode value) => lazy_modeAsInt = value.value;

  /// the GPU that is used for the entire model when split_mode is
  /// LLAMA_SPLIT_MODE_NONE
  @ffi.Int32()
  external int main_gpu;

  /// proportion of the model (layers or rows) to offload to each GPU, size:
  /// llama_max_devices()
  external ffi.Pointer<ffi.Float> tensor_split;

  /// Called with a progress value between 0.0 and 1.0. Pass NULL to disable. If
  /// the provided progress_callback returns true, model loading continues. If
  /// it returns false, model loading is immediately aborted.
  external ffi.Pointer<
    ffi.NativeFunction<
      ffi.Bool Function(ffi.Float progress, ffi.Pointer<ffi.Void> user_data)
    >
  >
  progress_callback;

  /// context pointer passed to the progress callback
  external ffi.Pointer<ffi.Void> progress_callback_user_data;

  /// override key-value pairs of the model meta data
  external ffi.Pointer<llama_model_kv_override> kv_overrides;

  /// only load the vocabulary, no weights
  @ffi.Bool()
  external bool vocab_only;

  /// validate model tensor data
  @ffi.Bool()
  external bool check_tensors;

  /// use extra buffer types (used for weight repacking)
  @ffi.Bool()
  external bool use_extra_bufts;

  /// bypass host buffer allowing extra buffers to be used
  @ffi.Bool()
  external bool no_host;

  /// only load metadata and simulate memory allocations
  @ffi.Bool()
  external bool no_alloc;

  /// whether to load MTP layers
  @ffi.Bool()
  external bool load_mtp;

  static ffi.Pointer<llama_model_params> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Pointer<ggml_backend_device>> devices,
    required ffi.Pointer<llama_model_tensor_buft_override>
    tensor_buft_overrides,
    required int n_gpu_layers,
    required llama_split_mode split_mode,
    required llama_load_mode load_mode,
    required llama_lazy_mode lazy_mode,
    required int main_gpu,
    required ffi.Pointer<ffi.Float> tensor_split,
    required ffi.Pointer<
      ffi.NativeFunction<
        ffi.Bool Function(ffi.Float progress, ffi.Pointer<ffi.Void> user_data)
      >
    >
    progress_callback,
    required ffi.Pointer<ffi.Void> progress_callback_user_data,
    required ffi.Pointer<llama_model_kv_override> kv_overrides,
    required bool vocab_only,
    required bool check_tensors,
    required bool use_extra_bufts,
    required bool no_host,
    required bool no_alloc,
    required bool load_mtp,
  }) => $allocator<llama_model_params>()
    ..ref.devices = devices
    ..ref.tensor_buft_overrides = tensor_buft_overrides
    ..ref.n_gpu_layers = n_gpu_layers
    ..ref.split_mode = split_mode
    ..ref.load_mode = load_mode
    ..ref.lazy_mode = lazy_mode
    ..ref.main_gpu = main_gpu
    ..ref.tensor_split = tensor_split
    ..ref.progress_callback = progress_callback
    ..ref.progress_callback_user_data = progress_callback_user_data
    ..ref.kv_overrides = kv_overrides
    ..ref.vocab_only = vocab_only
    ..ref.check_tensors = check_tensors
    ..ref.use_extra_bufts = use_extra_bufts
    ..ref.no_host = no_host
    ..ref.no_alloc = no_alloc
    ..ref.load_mtp = load_mtp;
}

final class llama_model_tensor_buft_override extends ffi.Opaque {}

enum llama_pooling_type {
  LLAMA_POOLING_TYPE_UNSPECIFIED(-1),
  LLAMA_POOLING_TYPE_NONE(0),
  LLAMA_POOLING_TYPE_MEAN(1),
  LLAMA_POOLING_TYPE_CLS(2),
  LLAMA_POOLING_TYPE_LAST(3),

  /// used by reranking models to attach the classification head to the graph
  LLAMA_POOLING_TYPE_RANK(4);

  final int value;
  const llama_pooling_type(this.value);

  static llama_pooling_type fromValue(int value) => switch (value) {
    -1 => LLAMA_POOLING_TYPE_UNSPECIFIED,
    0 => LLAMA_POOLING_TYPE_NONE,
    1 => LLAMA_POOLING_TYPE_MEAN,
    2 => LLAMA_POOLING_TYPE_CLS,
    3 => LLAMA_POOLING_TYPE_LAST,
    4 => LLAMA_POOLING_TYPE_RANK,
    _ => throw ArgumentError('Unknown value for llama_pooling_type: $value'),
  };
}

enum llama_rope_scaling_type {
  LLAMA_ROPE_SCALING_TYPE_UNSPECIFIED(-1),
  LLAMA_ROPE_SCALING_TYPE_NONE(0),
  LLAMA_ROPE_SCALING_TYPE_LINEAR(1),
  LLAMA_ROPE_SCALING_TYPE_YARN(2),
  LLAMA_ROPE_SCALING_TYPE_LONGROPE(3);

  static const LLAMA_ROPE_SCALING_TYPE_MAX_VALUE =
      LLAMA_ROPE_SCALING_TYPE_LONGROPE;

  final int value;
  const llama_rope_scaling_type(this.value);

  static llama_rope_scaling_type fromValue(int value) => switch (value) {
    -1 => LLAMA_ROPE_SCALING_TYPE_UNSPECIFIED,
    0 => LLAMA_ROPE_SCALING_TYPE_NONE,
    1 => LLAMA_ROPE_SCALING_TYPE_LINEAR,
    2 => LLAMA_ROPE_SCALING_TYPE_YARN,
    3 => LLAMA_ROPE_SCALING_TYPE_LONGROPE,
    _ => throw ArgumentError(
      'Unknown value for llama_rope_scaling_type: $value',
    ),
  };

  @override
  String toString() {
    if (this == LLAMA_ROPE_SCALING_TYPE_LONGROPE)
      return "llama_rope_scaling_type.LLAMA_ROPE_SCALING_TYPE_LONGROPE, llama_rope_scaling_type.LLAMA_ROPE_SCALING_TYPE_MAX_VALUE";
    return super.toString();
  }
}

